import { SCHEMA, STATUSES, blankWorkspace, newIdea, economics, assess, validateWorkspace, pitchMarkdown, assistantPrompt, stamp } from './model.mjs';
import { exampleWorkspace } from './example.mjs';

const KEY = 'tomboj.make-the-case.v1', app = document.querySelector('#app');
let state, stage = 'develop', tab = 'scope', storageOK = true;
try { const saved = localStorage.getItem(KEY); state = saved ? validateWorkspace(JSON.parse(saved)) : exampleWorkspace(); } catch { state = exampleWorkspace(); storageOK = false; }
const escape = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => n == null ? '—' : new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(n);
const current = () => state.ideas.find(i => i.id === state.selectedId) || state.ideas[0];
const field = (name, label, value, options = {}) => `<label class="field ${options.wide ? 'wide' : ''}"><span>${escape(label)}</span>${options.area ? `<textarea data-field="${name}" rows="${options.rows || 3}" placeholder="${escape(options.placeholder || '')}">${escape(value)}</textarea>` : options.choices ? `<select data-field="${name}">${options.choices.map(c => `<option ${c === value ? 'selected' : ''}>${escape(c)}</option>`).join('')}</select>` : `<input data-field="${name}" class="${options.title ? 'title-input' : ''}" type="${options.number ? 'number' : options.date ? 'date' : 'text'}" ${options.number ? `min="${options.positive ? '0.1' : '0'}" step="any" ${options.percent ? 'max="100"' : ''}` : ''} value="${escape(value ?? '')}" placeholder="${escape(options.placeholder || '')}">`}${options.hint ? `<small>${escape(options.hint)}</small>` : ''}</label>`;
function toast(message) { const t = document.querySelector('#toast'); t.textContent = message; t.classList.add('visible'); clearTimeout(toast.timer); toast.timer = setTimeout(() => t.classList.remove('visible'), 4500); }
function save() { state.updatedAt = stamp(); for (const idea of state.ideas) if (idea.status === 'Testing' && (idea.permissions !== 'Confirmed' || !idea.reviewer.trim() || !idea.approvalEvidence.trim())) { idea.status = 'Needs review'; const choice = document.querySelector('[data-field="status"]'); if (idea.id === current().id && choice) choice.value = idea.status; } try { localStorage.setItem(KEY, JSON.stringify(state)); storageOK = true; } catch { storageOK = false; } const el = document.querySelector('#save-state'); if (el) el.textContent = storageOK ? 'Saved in this browser. Download a workspace file to keep a portable copy.' : 'Browser saving is unavailable. Download your workspace to retain changes.'; }
function download(name, body, type = 'text/plain') { const url = URL.createObjectURL(new Blob([body], { type })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
async function copy(text) { try { await navigator.clipboard.writeText(text); toast('Copied.'); } catch { modal('Copy your text', '<p>Select the text below and copy it.</p><textarea id="copy-fallback" readonly></textarea>'); const t = document.querySelector('#copy-fallback'); t.value = text; t.focus(); t.select(); } }
function modal(title, body) { document.querySelector('#dialog-content').innerHTML = `<div class="dialog-top"><h2>${escape(title)}</h2><button class="close" data-close aria-label="Close dialog">×</button></div>${body}`; const d = document.querySelector('#dialog'); if (!d.open) d.showModal(); }
function summaryHTML() {
  const i = current(), a = assess(i), m = a.money;
  return `<div class="panel forecast"><div class="summary-heading">Your working forecast<span>↗</span></div><div class="big-value">${m.available ? num(m.netHours) : '—'}<span class="unit">hrs / month</span></div><p>Potential net capacity after checking, correction, and ongoing support. ${state.fictional ? 'Illustrative assumptions.' : 'A forecast to test.'}</p><div class="rule"></div><div class="mini-metrics"><div><strong>${m.available ? num(m.tasks) : '—'}</strong><span>covered tasks / month</span></div><div><strong>${m.available ? num(m.monthlyCash) : '—'}</strong><span>recurring cash / month*</span></div></div><p class="tiny">*In the currency used for your cost inputs. Released time is not automatically financial savings.</p><button class="scenario" data-action="scenario">What if checking takes longer?</button></div><div class="panel status-panel ${a.tone}"><div class="summary-heading">Next decision</div><div class="status-title">${escape(a.title)}</div><ul class="check-list">${a.checks.slice(0, 4).map(c => `<li>${escape(c.text)}</li>`).join('') || '<li>Review the scope, evidence, and request with the relevant owner. This workspace does not grant approval.</li>'}</ul>${a.checks.length > 4 ? `<p class="tiny muted">${a.checks.length - 4} more conditions appear in the pitch.</p>` : ''}</div><div class="panel ai-note"><h3>Bring in your AI assistant</h3><p>Your context, open questions, and unused ideas travel with the briefing. Use an assistant your organization permits.</p><button class="button small" data-action="ai">Prepare AI briefing ↗</button><p class="tiny muted">The workspace itself does not call an AI model.</p></div>`;
}
function ideasHTML() {
  return `<section class="panel"><p class="eyebrow">01 / KEEP THE WHOLE PICTURE</p><h2>Your work is the starting point.</h2><p class="section-intro">No business case needed yet. Start with what happens and what you would like to improve.</p><div class="form-grid">${field('context.company', 'Company or team', state.context.company, { placeholder: 'A short description is enough' })}${field('context.role', 'Your role or contribution', state.context.role, { placeholder: 'What you know about this work' })}${field('context.goal', 'What should get better?', state.context.goal, { area: true, wide: true, placeholder: 'For customers, colleagues, or the business' })}${field('context.constraints', 'What conditions do we need to work within?', state.context.constraints, { area: true, wide: true, placeholder: 'Tools, data, time, authority, or what is still unknown' })}</div></section><section class="panel"><h2>Keep the ideas. Choose a focus.</h2><p class="section-intro">Develop one now. The rest stay available to combine, revisit, or hand to a collaborator.</p>${state.ideas.map((i, index) => `<article class="idea-card"><div><p class="eyebrow">${String(index + 1).padStart(2, '0')} / ${escape(i.status)}</p><h3>${escape(i.title)}</h3><p>${escape(i.problem || 'Describe the opportunity as you learn more.')}</p>${i.selectionReason ? `<p>${escape(i.selectionReason)}</p>` : ''}</div><button class="button small ${i.id === state.selectedId ? 'lime' : ''}" data-select="${escape(i.id)}">${i.id === state.selectedId ? 'Develop this focus' : 'Make this my focus'}</button></article>`).join('')}<details><summary>Add several ideas at once</summary><label class="field"><span>One idea per line</span><textarea id="bulk-ideas" rows="5" placeholder="Stop retyping the same customer update&#10;Make handoffs clearer&#10;Find answers in our approved guidance"></textarea></label><button class="button" data-action="bulk-add">Keep these ideas</button></details></section>`;
}
function scopeHTML(i) { return `${field('title', 'Working title', i.title, { title: true })}${field('problem', 'What happens today, and why is it a problem?', i.problem, { area: true, placeholder: 'Describe one real example. Who encounters it?' })}${field('outcome', 'What useful outcome would change?', i.outcome, { area: true, rows: 2 })}<div class="form-grid">${field('currentWork', 'Today', i.currentWork, { area: true, rows: 5 })}${field('proposedWork', 'Proposed change', i.proposedWork, { area: true, rows: 5, hint: 'What could AI do? What would people still do?' })}</div><div style="height:17px"></div>${field('exclusions', 'What stays outside this first step?', i.exclusions, { area: true, rows: 2 })}${field('selectionReason', 'Why focus on this now?', i.selectionReason, { area: true, rows: 2, hint: 'Value, readiness, dependencies, or a question worth investigating. The choice can change.' })}`; }
function peopleHTML(i) { return `${field('originator', 'Who noticed or suggested this?', i.originator)}${field('businessOwner', 'Who could own the business outcome?', i.businessOwner, { hint: 'A proposed owner is not an accepted assignment.' })}${field('collaborators', 'Who would help, review, build, or support it?', i.collaborators, { area: true, hint: 'You do not have to build the whole idea yourself.' })}${field('audiences', 'Who experiences the change, and what changes for them?', i.audiences, { area: true, hint: 'Include users, approvers, support, customers, and partners where relevant.' })}${field('learning', 'What communication, learning, and support would they need?', i.learning, { area: true })}<p class="section-label">Permission for this specific use</p>${field('permissions', 'Tool, data, and action permissions', i.permissions, { choices: ['Unknown', 'Needs review', 'Confirmed', 'Not permitted'] })}<div class="form-grid">${field('reviewer', 'Confirmed by', i.reviewer)}${field('approvalEvidence', 'Decision reference', i.approvalEvidence, { hint: 'A source you are allowed to record; do not include secrets.' })}</div><p class="inline-note">Identify the relevant Legal, compliance, privacy, security, safety, and business reviewers. An approved tool does not approve every use. A generated pitch is a request, not permission.</p>`; }
function evidenceHTML(i) {
  const metrics = [ ['volume','Eligible tasks / month'], ['baselineMinutes','Current minutes / task'], ['draftMinutes','New draft / processing minutes'], ['reviewMinutes','Check + correct minutes / task'], ['coverage','Coverage (%)'], ['uptake','Expected uptake (%)'], ['supportHours','Ongoing support hours / month'] ];
  return `${field('baselineSource', 'What supports the current baseline?', i.baselineSource, { area: true, hint: 'Source, date, sample, and limitations. If unknown, describe how you will measure it.' })}${field('evidence', 'What else supports or challenges the idea?', i.evidence, { area: true, hint: 'Keep observed facts separate from estimates and hypotheses.' })}<p class="section-label">Change an assumption. See what follows.</p><div class="form-grid">${metrics.map(([key, label]) => field(`metrics.${key}`, label, i.metrics[key], { number: true, percent: ['coverage','uptake'].includes(key), placeholder: 'Unknown', hint: key === 'reviewMinutes' ? 'Include fact-checking, exceptions, and rework.' : undefined })).join('')}</div><details><summary>Cost and optional financial scenario</summary><p class="help-copy">Use one currency for every cost. These inputs describe assumptions, not verified savings. Review/correction time is included above; support time and setup effort are costed below. Do not add the capacity estimate to a financial benefit again.</p><div class="form-grid">${[['license','Licenses / usage per month'],['otherCost','Other recurring cash per month'],['setupCash','One-off setup cash'],['setupHours','Setup hours'],['hourlyRate','Cost per hour'],['monthlyBenefit','Attributable financial benefit / month'],['months','Evaluation period (months)']].map(([key, label]) => field(`metrics.${key}`, label, i.metrics[key], { number: true, positive: key === 'months', placeholder: 'Not established' })).join('')}</div><div id="financial-summary"></div></details><p class="section-label">How would you learn whether it helped?</p>${field('testPlan', 'What is the next investigation or bounded test?', i.testPlan, { area: true })}${field('quality', 'What quality and risk conditions must hold?', i.quality, { area: true })}${field('stopRule', 'When would you continue, adapt, pause, or stop?', i.stopRule, { area: true })}${field('reviewDate', 'When should the next decision happen?', i.reviewDate, { date: true })}`;
}
function developHTML() { const i = current(); return `<section class="panel"><p class="eyebrow">02 / DEVELOP ONE WORTHWHILE CASE</p><h2>${escape(i.title)}</h2><p class="section-intro">Make the next step clear enough for someone to decide.</p><div class="subtabs" role="group" aria-label="Develop the case">${[['scope','Scope'],['people','People & permissions'],['evidence','Evidence & cost']].map(([k,v]) => `<button class="subtab ${tab === k ? 'active' : ''}" data-tab="${k}" aria-pressed="${tab === k}">${v}</button>`).join('')}</div>${tab === 'scope' ? scopeHTML(i) : tab === 'people' ? peopleHTML(i) : evidenceHTML(i)}<div class="actions"><button class="button primary" data-action="next-tab">${tab === 'scope' ? 'Continue to people →' : tab === 'people' ? 'Continue to evidence →' : 'Prepare the pitch →'}</button><button class="button quiet" data-action="ai">Work through this with AI ↗</button></div></section>`; }
function advanceHTML() { const i = current(); return `<section class="panel no-print"><p class="eyebrow">03 / MAKE A CLEAR REQUEST</p><h2>Give someone a decision to make.</h2><p class="section-intro">The next step can be discovery, a specialist review, or a bounded test.</p>${field('request', 'What exactly are you asking for?', i.request, { area: true, hint: 'Include time, people, budget, scope, and who needs to decide. Unknowns are valid.' })}<div class="actions"><button class="button primary" data-action="copy-pitch">Copy pitch</button><button class="button" data-action="download-pitch">Download pitch</button><button class="button" data-action="print">Print / save PDF</button></div></section><section class="panel"><h2>Working pitch</h2><p class="section-intro no-print">Built from your recorded inputs. Missing information remains visible.</p><pre class="pitch-preview" id="pitch-preview">${escape(pitchMarkdown(state, i))}</pre></section><section class="panel no-print"><h2>Make the contribution visible.</h2><p class="section-intro">Keep the evidence of your work as it develops. Include shared credit.</p>${field('contribution', 'What have you contributed so far?', i.contribution, { area: true, hint: 'Investigation, domain knowledge, coordination, testing, delivery, or adoption. State what actually happened.' })}${field('actualResult', 'What happened after the work or test?', i.actualResult, { area: true, hint: 'Leave blank until there is a result. A forecast is not an achievement.' })}<div class="form-grid">${field('resultSource', 'Result evidence / source', i.resultSource)}${field('resultReviewer', 'Who can confirm it?', i.resultReviewer)}</div>${field('assistantNotes', 'Learning and useful feedback to carry forward', i.assistantNotes, { area: true })}<details><summary>Record a decision or next step</summary>${field('status', 'Current stage', i.status, { choices: STATUSES, hint: 'Testing requires a recorded permission decision. Status records do not grant authority.' })}<label class="field"><span>Decision or next step</span><input id="decision-title" placeholder="For example: gather representative timing"></label><label class="field"><span>Why, and what happens next?</span><textarea id="decision-reason" rows="3"></textarea></label><label class="field"><span>Who made or owns this decision?</span><input id="decision-who"></label><button class="button" data-action="log-decision">Add to decision history</button></details><div id="history">${historyHTML(i)}</div></section>`; }
function historyHTML(i) { return i.history.slice().reverse().map(h => `<div class="history-entry"><span class="tiny muted">${escape(h.date.slice(0,10))} · ${escape(h.who || 'Owner not recorded')}</span><strong>${escape(h.decision)}</strong><p>${escape(h.reason)}</p></div>`).join(''); }
function render() {
  const i = current();
  app.innerHTML = `<div class="workspace-bar"><div class="data-label"><span class="dot"></span><strong>${state.fictional ? 'Fictional example' : 'Your workspace'}</strong><span>· ${escape(state.context.company || 'Start with your work')}</span></div><div class="actions"><button class="button small" data-action="start">Start my own</button><button class="button small" data-action="example">Load example</button><button class="button small" data-action="import">Open saved work</button><button class="button small" data-action="export">Download workspace ↓</button></div></div><div class="layout"><aside class="sidebar" aria-label="Your ideas"><div class="sidebar-top"><h2>Your opportunities</h2><span class="counter">${state.ideas.length}</span></div><div class="idea-list">${state.ideas.map((x,index) => `<button class="idea-button ${x.id === i.id ? 'active' : ''}" data-select="${escape(x.id)}" aria-pressed="${x.id === i.id}"><span class="idea-code">IDEA ${String(index + 1).padStart(2,'0')}</span><span class="idea-name">${escape(x.title)}</span><span class="idea-status">${escape(x.status)}</span></button>`).join('')}</div><div class="sidebar-bottom"><button class="button small" data-action="add">+ Keep an idea</button><p>Selecting a focus keeps every other idea. You can return to it later.</p></div></aside><main id="main" class="main-shell" tabindex="-1"><nav class="steps" aria-label="Workflow">${[['ideas','Collect your ideas'],['develop','Develop a case'],['advance','Pitch & progress']].map(([k,v],index) => `<button class="step ${stage === k ? 'active' : ''}" data-stage="${k}" aria-current="${stage === k ? 'step' : 'false'}"><span>0${index + 1}</span>${v}</button>`).join('')}</nav><div class="content-grid"><div>${stage === 'ideas' ? ideasHTML() : stage === 'develop' ? developHTML() : advanceHTML()}<p id="save-state" class="save-state"></p></div><aside id="summary" class="summary" aria-label="Forecast and next decision">${summaryHTML()}</aside></div></main></div>`;
  save(); updateDerived();
}
function updateDerived() { const s = document.querySelector('#summary'); if (s) s.innerHTML = summaryHTML(); const p = document.querySelector('#pitch-preview'); if (p) p.textContent = pitchMarkdown(state, current()); const financial = document.querySelector('#financial-summary'); if (financial) { const m = economics(current().metrics); financial.innerHTML = `<p class="inline-note">${m.available && m.roi !== null ? `Scenario ROI over ${num(m.horizon)} months: <strong>${num(m.roi * 100)}%</strong>. Cost basis ${num(m.cost)}; attributable financial benefit ${num(m.benefits)}. Check all inputs and the cost boundary before making a financial claim.` : 'Financial return is not established. Add an attributable financial benefit, a period, and the cost inputs if appropriate. Time released alone does not establish financial benefit.'}</p>`; } }
app.addEventListener('input', e => { const name = e.target.dataset.field; if (!name) return; const i = current(); if (name.startsWith('metrics.')) { const valid = e.target.validity.valid; e.target.setAttribute('aria-invalid', String(!valid)); i.metrics[name.slice(8)] = !valid || e.target.value === '' ? null : Number(e.target.value); } else if (!e.target.validity.valid) return; else if (name.startsWith('context.')) state.context[name.slice(8)] = e.target.value; else if (name !== 'status') i[name] = e.target.value; save(); updateDerived(); });
app.addEventListener('change', e => { const name = e.target.dataset.field; if (name === 'status') { const i = current(); if (e.target.value === 'Testing' && (i.permissions !== 'Confirmed' || !i.reviewer.trim() || !i.approvalEvidence.trim())) { e.target.value = i.status; toast('Record confirmed permissions, who confirmed them, and the decision reference before recording a test in progress.'); return; } i.status = e.target.value; save(); } if (name === 'title' || name === 'status' || name?.startsWith('context.')) { const buttons = document.querySelectorAll('.idea-button'); buttons.forEach((b,index) => { b.querySelector('.idea-name').textContent = state.ideas[index].title; b.querySelector('.idea-status').textContent = state.ideas[index].status; }); } });
app.addEventListener('click', async e => {
  const b = e.target.closest('button'); if (!b) return;
  if (b.dataset.select) { state.selectedId = b.dataset.select; stage = 'develop'; tab = 'scope'; render(); return; }
  if (b.dataset.stage) { stage = b.dataset.stage; render(); return; }
  if (b.dataset.tab) { tab = b.dataset.tab; render(); return; }
  const action = b.dataset.action;
  if (action === 'next-tab') { if (tab === 'scope') tab = 'people'; else if (tab === 'people') tab = 'evidence'; else stage = 'advance'; render(); document.querySelector('#main').focus({ preventScroll: true }); }
  if (action === 'start' || action === 'example') { modal(action === 'start' ? 'Start with your own work' : 'Load the fictional example', `<p>This replaces the workspace currently open in this browser. Download a copy first if you want to keep it.</p><div class="actions"><button class="button" data-download-current>Download current workspace</button><button class="button primary" data-replace="${action}">${action === 'start' ? 'Start a blank workspace' : 'Load Northstar example'}</button></div>`); }
  if (action === 'export') { download('make-the-case-workspace.json', JSON.stringify(state, null, 2), 'application/json'); toast('Workspace downloaded. Open it later to continue.'); }
  if (action === 'import') document.querySelector('#import-file').click();
  if (action === 'add') { if (state.ideas.length >= 200) return toast('This workspace supports up to 200 ideas.'); const idea = newIdea(); state.ideas.push(idea); state.selectedId = idea.id; stage = 'develop'; tab = 'scope'; render(); document.querySelector('[data-field="title"]').focus(); }
  if (action === 'bulk-add') { const titles = document.querySelector('#bulk-ideas').value.split('\n').map(t => t.trim()).filter(Boolean); if (!titles.length) return toast('Add one idea per line.'); if (titles.some(t => t.length > 12000) || state.ideas.length + titles.length > 200) return toast('Keep the workspace within 200 ideas and shorten any very long title.'); state.ideas.push(...titles.map(t => newIdea(t))); save(); render(); toast(`Kept ${titles.length} ideas. Your selected focus is unchanged.`); }
  if (action === 'scenario') { stage = 'develop'; tab = 'evidence'; render(); const input = document.querySelector('[data-field="metrics.reviewMinutes"]'); input.focus(); input.select(); toast('Change check + correct minutes. The forecast and next decision update from your inputs.'); }
  if (action === 'copy-pitch') await copy(pitchMarkdown(state, current()));
  if (action === 'download-pitch') download('make-the-case-pitch.md', pitchMarkdown(state, current()), 'text/markdown');
  if (action === 'print') window.print();
  if (action === 'ai') { modal('Work through the case with AI', '<p>Copy this briefing into your approved AI assistant. It includes your current context and asks the assistant to work through the missing information with you. Bring useful answers back into the fields, then download the workspace to continue later.</p><p class="help-copy">Review the briefing before sharing it. The workspace does not send it automatically.</p><textarea id="ai-briefing" readonly aria-label="AI briefing"></textarea><div class="actions"><button class="button primary" data-copy-ai>Copy briefing</button><button class="button" data-download-ai>Download briefing</button></div>'); document.querySelector('#ai-briefing').value = assistantPrompt(state, current()); }
  if (action === 'log-decision') { const decision = document.querySelector('#decision-title').value.trim(), reason = document.querySelector('#decision-reason').value.trim(), who = document.querySelector('#decision-who').value.trim(); if (!decision || !reason || !who) return toast('Add the decision, reason, and responsible person.'); current().history.push({ date: stamp(), decision, reason, who }); save(); render(); toast('Decision recorded. Earlier entries are retained.'); }
});
document.querySelector('#dialog').addEventListener('click', async e => { const b = e.target.closest('button'); if (!b) return; if (b.hasAttribute('data-close')) document.querySelector('#dialog').close(); if (b.hasAttribute('data-download-current')) download('make-the-case-workspace.json', JSON.stringify(state, null, 2), 'application/json'); if (b.dataset.replace) { state = b.dataset.replace === 'start' ? blankWorkspace() : exampleWorkspace(); stage = b.dataset.replace === 'start' ? 'ideas' : 'develop'; tab = 'scope'; render(); document.querySelector('#dialog').close(); } if (b.hasAttribute('data-copy-ai')) await copy(document.querySelector('#ai-briefing').value); if (b.hasAttribute('data-download-ai')) download('make-the-case-ai-briefing.txt', document.querySelector('#ai-briefing').value); });
document.querySelector('#import-file').addEventListener('change', async e => { const file = e.target.files?.[0]; e.target.value = ''; if (!file) return; try { if (file.size > 1000000) throw new Error('Use a workspace file smaller than 1 MB.'); const incoming = validateWorkspace(JSON.parse(await file.text())); modal('Open your saved workspace', `<p>Found ${incoming.ideas.length} ideas for ${escape(incoming.context.company || 'your team')}. This will replace the current browser workspace. Download your current work first if you want to retain both.</p><div class="actions"><button class="button" data-download-current>Download current workspace</button><button class="button primary" id="confirm-import">Open this workspace</button></div>`); document.querySelector('#confirm-import').onclick = () => { state = incoming; stage = 'develop'; tab = 'scope'; render(); document.querySelector('#dialog').close(); toast('Workspace restored. All ideas and decisions retained.'); }; } catch (error) { toast(error instanceof SyntaxError ? 'This is not a valid JSON workspace file.' : error.message); } });
document.querySelector('#help').addEventListener('click', () => modal('A useful next step, not a blank page', '<ol><li><strong>Collect.</strong> Describe your work and keep your ideas. You can start with a frustration, one idea, several ideas, or an existing proposal.</li><li><strong>Develop.</strong> Work through scope, affected people, evidence, costs, and the help you need. You do not have to build the solution yourself.</li><li><strong>Advance.</strong> Create a clear request, record decisions, and keep evidence of what you contributed.</li></ol><p>Use <strong>Prepare AI briefing</strong> to continue with an approved assistant. Download your workspace to resume on another device or session. Browser storage can be cleared; your downloaded file is the portable record.</p><p>The Northstar example is fictional. Forecasts change with your assumptions. The browser workspace uses explicit rules and calculations, with no live model calls or automatic sharing.</p><p><a href="start-here.md">Read the starting guide</a> · <a href="case-study.html">See the method and evidence</a></p>'));
render();
